CREATE TABLE roles (name TEXT PRIMARY KEY CHECK(name IN ('CUSTOMER','ADMIN')));
INSERT INTO roles VALUES ('CUSTOMER'),('ADMIN');
CREATE TABLE users (id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,mobile TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'CUSTOMER' REFERENCES roles(name),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sessions (id TEXT PRIMARY KEY,user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE password_resets (token_hash TEXT PRIMARY KEY,user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE categories (id SERIAL PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT NOT NULL DEFAULT '',image TEXT NOT NULL DEFAULT '',parent_id INT REFERENCES categories(id),active BOOLEAN NOT NULL DEFAULT TRUE,seo_title TEXT NOT NULL DEFAULT '',seo_description TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(parent_id IS NULL OR parent_id <> id));
CREATE TABLE brands (id SERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE products (id SERIAL PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,sku TEXT NOT NULL UNIQUE,category_id INT NOT NULL REFERENCES categories(id),brand_id INT NOT NULL REFERENCES brands(id),description TEXT NOT NULL,short_description TEXT NOT NULL,price NUMERIC(12,2) NOT NULL CHECK(price>=0),original_price NUMERIC(12,2) NOT NULL CHECK(original_price>=price),cost_price NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(cost_price>=0),low_stock_threshold INT NOT NULL DEFAULT 5 CHECK(low_stock_threshold>=0),specifications JSONB NOT NULL DEFAULT '{}',features JSONB NOT NULL DEFAULT '[]',seo_title TEXT NOT NULL DEFAULT '',seo_description TEXT NOT NULL DEFAULT '',active BOOLEAN NOT NULL DEFAULT TRUE,featured BOOLEAN NOT NULL DEFAULT FALSE,sales INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE product_images (id SERIAL PRIMARY KEY,product_id INT NOT NULL REFERENCES products(id) ON DELETE CASCADE,url TEXT NOT NULL,position INT NOT NULL DEFAULT 0);
CREATE TABLE product_variants (id SERIAL PRIMARY KEY,product_id INT NOT NULL REFERENCES products(id) ON DELETE CASCADE,name TEXT NOT NULL,sku TEXT NOT NULL UNIQUE,attributes JSONB NOT NULL DEFAULT '{}',price NUMERIC(12,2) NOT NULL CHECK(price>=0),stock INT NOT NULL CHECK(stock>=0),image TEXT NOT NULL DEFAULT '',active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE cart (id SERIAL PRIMARY KEY,user_id INT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE cart_items (id SERIAL PRIMARY KEY,cart_id INT NOT NULL REFERENCES cart(id) ON DELETE CASCADE,variant_id INT NOT NULL REFERENCES product_variants(id),quantity INT NOT NULL CHECK(quantity>0 AND quantity<=99),UNIQUE(cart_id,variant_id));
CREATE TABLE wishlist (id SERIAL PRIMARY KEY,user_id INT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE wishlist_items (id SERIAL PRIMARY KEY,wishlist_id INT NOT NULL REFERENCES wishlist(id) ON DELETE CASCADE,product_id INT NOT NULL REFERENCES products(id) ON DELETE CASCADE,UNIQUE(wishlist_id,product_id));
CREATE TABLE addresses (id SERIAL PRIMARY KEY,user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,label TEXT NOT NULL DEFAULT 'Home',first_name TEXT NOT NULL,last_name TEXT NOT NULL,email TEXT NOT NULL,mobile TEXT NOT NULL,address TEXT NOT NULL,apartment TEXT NOT NULL DEFAULT '',city TEXT NOT NULL,state TEXT NOT NULL,pincode TEXT NOT NULL,country TEXT NOT NULL DEFAULT 'India',is_default BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX default_address_per_user ON addresses(user_id) WHERE is_default;
CREATE TABLE coupons (id SERIAL PRIMARY KEY,code TEXT NOT NULL UNIQUE,discount_type TEXT NOT NULL CHECK(discount_type IN ('PERCENT','FIXED')),value NUMERIC(12,2) NOT NULL CHECK(value>0),min_order NUMERIC(12,2) NOT NULL DEFAULT 0,max_discount NUMERIC(12,2),starts_at TIMESTAMPTZ NOT NULL DEFAULT now(),expires_at TIMESTAMPTZ NOT NULL,usage_limit INT NOT NULL DEFAULT 100 CHECK(usage_limit>0),used_count INT NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(expires_at>starts_at),CHECK(discount_type <> 'PERCENT' OR value <=100));
CREATE TABLE orders (id SERIAL PRIMARY KEY,number TEXT NOT NULL UNIQUE,user_id INT NOT NULL REFERENCES users(id),shipping_address JSONB NOT NULL,billing_address JSONB NOT NULL,delivery TEXT NOT NULL CHECK(delivery IN ('STANDARD','EXPRESS')),status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','CONFIRMED','PROCESSING','SHIPPED','DELIVERED','CANCELLED','RETURN_REQUESTED','RETURNED','REFUNDED')),payment_status TEXT NOT NULL DEFAULT 'UNPAID' CHECK(payment_status IN ('UNPAID','PAID','REFUNDED')),subtotal NUMERIC(12,2) NOT NULL,discount NUMERIC(12,2) NOT NULL DEFAULT 0,shipping NUMERIC(12,2) NOT NULL DEFAULT 0,tax NUMERIC(12,2) NOT NULL DEFAULT 0,total NUMERIC(12,2) NOT NULL,coupon_id INT REFERENCES coupons(id),expected_delivery TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE order_items (id SERIAL PRIMARY KEY,order_id INT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id INT NOT NULL REFERENCES products(id),variant_id INT NOT NULL REFERENCES product_variants(id),name TEXT NOT NULL,variant TEXT NOT NULL,sku TEXT NOT NULL,image TEXT NOT NULL,quantity INT NOT NULL CHECK(quantity>0),price NUMERIC(12,2) NOT NULL CHECK(price>=0));
CREATE TABLE payments (id SERIAL PRIMARY KEY,order_id INT NOT NULL UNIQUE REFERENCES orders(id),method TEXT NOT NULL,provider_reference TEXT,status TEXT NOT NULL DEFAULT 'UNPAID',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE coupon_usage (id SERIAL PRIMARY KEY,coupon_id INT NOT NULL REFERENCES coupons(id),user_id INT NOT NULL REFERENCES users(id),order_id INT NOT NULL UNIQUE REFERENCES orders(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reviews (id SERIAL PRIMARY KEY,product_id INT NOT NULL REFERENCES products(id),user_id INT NOT NULL REFERENCES users(id),rating INT NOT NULL CHECK(rating BETWEEN 1 AND 5),title TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(product_id,user_id));
CREATE TABLE review_images (id SERIAL PRIMARY KEY,review_id INT NOT NULL REFERENCES reviews(id) ON DELETE CASCADE,url TEXT NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY,value JSONB NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE newsletter (email TEXT PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX products_category ON products(category_id,active);
CREATE INDEX products_brand ON products(brand_id);
CREATE INDEX products_created ON products(created_at);
CREATE INDEX variants_product ON product_variants(product_id);
CREATE INDEX orders_customer ON orders(user_id,created_at);
CREATE INDEX orders_status ON orders(status);
CREATE INDEX orders_created ON orders(created_at);
CREATE INDEX reviews_product ON reviews(product_id,status);
CREATE INDEX addresses_customer ON addresses(user_id);
CREATE INDEX sessions_user ON sessions(user_id);
